begin;

update public.spell_catalog set name_ru='Кости земли', effect_summary='В выбранных точках земли в пределах 120 футов поднимаешь до шести каменных столбов диаметром 5 футов и высотой до 30 футов. Существо Среднего размера или меньше над возникающим столбом делает спасбросок Ловкости или поднимается вместе с ним. Если столб упирается в потолок, зажатая цель получает 6к6 дробящего урона и становится Опутанной. Столбы остаются как реальные каменные объекты.', author_description='Поле боя буквально перестраивается: столбами можно поднять союзника, перекрыть проход, создать высоту или прижать врага к потолку.', author_comment='Когда друид говорит «земля поможет», иногда земля приезжает снизу на тридцать футов.', upcast='За каждый уровень ячейки выше 6 можно создать ещё 2 столба.', notes='Каждый столб имеет КД 5 и 30 хитов. Разрушенный столб оставляет щебень как труднопроходимую местность. Зажатая цель может действием пройти проверку Силы или Ловкости против Сл заклинаний и освободиться.' where slug='bones-of-the-earth' and source_kind='official';

update public.spell_catalog set name_ru='Создание гомункула', effect_summary='За 1 час создаёшь единственного гомункула, связанного с тобой телепатически. При сотворении ты получаешь 2к4 колющего урона, который нельзя уменьшить. Во время долгого отдыха можешь передавать гомункулу часть своих Костей Хитов, временно увеличивая его максимум хитов до следующего отдыха.', author_description='Не временный призыв, а постоянный маленький слуга. Цена здесь не только золотом: заклинатель буквально вкладывает в создание часть собственной жизненной силы.', author_comment='Настоящая магическая инженерия начинается там, где инструкция требует кинжал за тысячу золотых и немного твоей крови.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Одновременно у тебя может быть только один гомункул, созданный этим заклинанием. Он погибает, когда погибаешь ты. Глина, пепел и корень мандрагоры расходуются; украшенный самоцветами кинжал стоимостью не менее 1000 зм не расходуется.', material='глина, пепел и корень мандрагоры — расходуются; украшенный самоцветами кинжал стоимостью не менее 1000 зм — не расходуется', material_cost_gp=1000, material_consumed=true, material_consumption='mixed' where slug='create-homunculus' and source_kind='official';

update public.spell_catalog set name_ru='Погребальная песнь', effect_summary='На срок до 1 минуты с концентрацией вокруг тебя звучит 60-футовая погребальная эманация. Выбранные тобой существа её игнорируют. Остальные не могут восстанавливать хиты; когда эманация впервые за ход достигает существа, оно входит в неё или заканчивает там ход, цель делает спасбросок Телосложения: при провале получает 3к10 некротического урона и падает ничком, при успехе получает половину урона и её скорость уменьшается вдвое до начала следующего хода.', author_description='Это не разовый удар, а движущаяся зона истощения вокруг заклинателя: лечение выключается, строй ломается, а каждый раунд рядом с тобой становится всё неприятнее.', author_comment='Песня настолько мрачная, что даже лечение предпочитает не вмешиваться.', upcast='Не усиливается обычной более высокой ячейкой; у заклинания есть отдельный вариант кругового сотворения.', notes='Одно существо проходит этот спасбросок не более одного раза за ход. При круговом сотворении длительность и последствия усиливаются, включая Истощение при провале.', casting_time='1 действие' where slug='dirge' and source_kind='official';

update public.spell_catalog set name_ru='Роща друида', effect_summary='За 10 минут защищаешь участок природы размером от 30-футового до 90-футового куба на 24 часа. Ты выбираешь существ, которых защита пропускает, и размещаешь внутри магические препятствия: густой туман, хватающий подлесок, древесных стражей и дополнительные природные эффекты вроде порывов ветра, шипов или стены ветра.', author_description='Это не одно боевое действие, а полноценная система обороны лагеря или священного места. Чем лучше выбран участок, тем сильнее заклинание ощущается как подготовленная крепость.', author_comment='Друиду не нужна сторожевая башня. Он просто объясняет лесу, кто сегодня не приглашён.', upcast='Не усиливается ячейкой более высокого уровня. Если сотворять заклинание в одном и том же месте каждый день в течение года, эффект становится постоянным до рассеивания.', notes='Материальный компонент расходуется. Часть эффектов требует отдельных спасбросков и действует только на существ, которых ты не назначил друзьями при сотворении.', material='омела, собранная золотым серпом при свете полной луны — расходуется', material_cost_gp=null, material_consumed=true, material_consumption='always' where slug='druid-grove' and source_kind='official';

update public.spell_catalog set name_ru='Сияющие сферы Эльминстера', effect_summary='На 1 час без концентрации вокруг тебя появляются шесть сияющих сфер. Реакцией можно поглотить одну сферу, когда получаешь урон кислотой, холодом, огнём, молнией или звуком, получив сопротивление этому типу до начала следующего хода. Бонусным действием можно запустить сферу в цель в пределах 120 футов: дальнобойная атака заклинанием наносит 3к6 выбранного стихийного урона.', author_description='Шесть зарядов, каждый из которых можно потратить либо на защиту, либо на атаку. Главная сила — возможность решать это уже по ситуации.', author_comment='Шесть маленьких аргументов вокруг головы: часть для врагов, часть на случай их аргументов.', upcast='Создаётся ещё 1 сфера за каждый уровень ячейки выше 6.', notes='Сфера тратится независимо от попадания атакой. Опал стоимостью не менее 1000 зм нужен как фокус и не расходуется.', material='опал стоимостью не менее 1000 зм — не расходуется', material_cost_gp=1000, material_consumed=false, material_consumption='none' where slug='elminster-s-effulgent-spheres' and source_kind='official';

update public.spell_catalog set name_ru='Платиновый щит Физбана', effect_summary='Бонусным действием окружаешь существо в пределах 60 футов серебристым полем на срок до 1 минуты с концентрацией. Цель получает половинное укрытие, сопротивление кислоте, холоду, огню, молнии и яду, а также эффект уклонения: при успешном спасброске Ловкости против эффекта на половину урона не получает урона вовсе, при провале получает только половину.', author_description='Очень плотный защитный пакет на одну цель: КД, стихии и почти легендарная живучесть против областных атак.', author_comment='Физбан назвал это щитом, хотя по факту принёс сразу три защитных способности.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Бонусным действием в последующие ходы поле можно перенести на другое существо в пределах 60 футов от текущего носителя. Драконья чешуя с платиновым покрытием стоимостью 500+ зм не расходуется.', material='драконья чешуя с платиновым покрытием стоимостью не менее 500 зм — не расходуется', material_cost_gp=500, material_consumed=false, material_consumption='none' where slug='fizban-s-platinum-shield' and source_kind='official';

update public.spell_catalog set name_ru='Гравитационный разлом', effect_summary='Создаёшь от себя линию гравитационной энергии длиной 100 футов и шириной 5 футов. Существа в линии делают спасбросок Телосложения, получая 8к8 урона силовым полем при провале или половину при успехе. Существа в пределах 10 футов от линии, но вне неё, также спасаются: при провале получают полный урон и притягиваются в область разлома.', author_description='Одна очень длинная линия не только наносит урон тем, кто уже стоит правильно, но и затягивает соседей внутрь.', author_comment='Гравитация решила, что строить врагов в линию можно и после начала заклинания.', upcast='Урон увеличивается на 1к8 за каждый уровень ячейки выше 6.', notes='Материальный компонент — горсть железных опилок; он не расходуется.', material='горсть железных опилок — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='gravity-fissure' and source_kind='official';

update public.spell_catalog set name_ru='Облечение пламенем', effect_summary='На срок до 10 минут с концентрацией покрываешь себя пламенем. Получаешь иммунитет к огню и сопротивление холоду. Существо, впервые за ход приблизившееся к тебе на 5 футов или закончившее там ход, получает 1к10 огненного урона. Действием можешь выпустить линию огня 15×5 футов: спасбросок Ловкости, 4к8 огненного урона при провале или половина при успехе.', author_description='Одновременно защита, наказание за ближний бой и повторяемая огненная атака действием.', author_comment='Если врагу всё ещё хочется обнять волшебника, это уже его осознанный выбор.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Пламя также ярко освещает область вокруг тебя.' where slug='investiture-of-flame' and source_kind='official';

update public.spell_catalog set name_ru='Облечение льдом', effect_summary='На срок до 10 минут с концентрацией покрываешь себя льдом. Получаешь иммунитет к холоду и сопротивление огню, игнорируешь дополнительную стоимость движения по льду и снегу, а земля в 10 футах вокруг тебя становится труднопроходимой для остальных. Действием выпускаешь 15-футовый конус холода: Телосложение, 4к6 урона холодом; при провале скорость цели также уменьшается вдвое до начала твоего следующего хода.', author_description='Защитная форма для контроля пространства: вокруг тебя трудно двигаться, а конус ещё сильнее тормозит тех, кто не прошёл спасбросок.', author_comment='Хорошая новость: лёд красивый. Плохая: вся карта вокруг тебя теперь тоже лёд.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='При успешном спасброске конус наносит половину урона без замедления. Требуется концентрация.' where slug='investiture-of-ice' and source_kind='official';

update public.spell_catalog set name_ru='Облечение камнем', effect_summary='На срок до 10 минут с концентрацией камень покрывает твоё тело. Ты получаешь сопротивление дробящему, колющему и рубящему урону от немагических атак, игнорируешь труднопроходимую местность из земли и камня и можешь проходить сквозь сплошную землю или камень как через воздух. Действием вызываешь землетрясение радиусом 15 футов: остальные существа на земле делают спасбросок Ловкости или падают ничком.', author_description='Форма для того, кто хочет стать частью местности: меньше бояться оружия, проходить через камень и регулярно сбивать окружающих с ног.', author_comment='Стены перестают быть препятствием примерно тогда же, когда ты сам начинаешь выглядеть как стена.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Нельзя заканчивать движение внутри сплошной земли или камня. Если это происходит, тебя выбрасывает в ближайшее свободное пространство, заклинание заканчивается, а ты Оглушён до конца следующего хода.' where slug='investiture-of-stone' and source_kind='official';

update public.spell_catalog set name_ru='Облечение ветром', effect_summary='На срок до 10 минут с концентрацией вокруг тебя вращается ветер. Дальнобойные атаки оружием по тебе совершаются с помехой, а ты получаешь скорость полёта 60 футов. Действием можешь создать видимый куб вихря 15 футов в точке до 60 футов: существа делают спасбросок Телосложения, получая 2к10 дробящего урона при провале или половину при успехе; Большие и меньшие цели при провале также отталкиваются до 10 футов от центра.', author_description='Очень мобильная защитная форма с повторяемым контролем: летай, усложняй стрелкам жизнь и раздвигай группы врагов ветром.', author_comment='В какой-то момент это перестаёт быть ветром вокруг мага и становится магом внутри собственной погоды.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Если заклинание заканчивается, пока ты летишь и у тебя нет другого способа удержаться в воздухе, ты падаешь.' where slug='investiture-of-wind' and source_kind='official';

update public.spell_catalog set name_ru='Ментальная тюрьма', effect_summary='Одно видимое существо в пределах 60 футов делает спасбросок Интеллекта; иммунное к Очарованию существо автоматически преуспевает. При любом результате цель получает 5к10 психического урона, но при провале ещё оказывается Опутанной иллюзорной тюрьмой, не видит и не слышит ничего за её пределами. Если цель покинет тюрьму, ударит сквозь неё в ближнем бою или протянет сквозь неё часть тела, получает ещё 10к10 психического урона и заклинание заканчивается.', author_description='Тюрьма существует только в голове цели, но последствия попытки пройти сквозь неё совершенно реальные.', author_comment='Самая экономная камера: стен нет, двери нет, а заключённый всё равно очень не хочет выходить.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация до 1 минуты. При успешном первоначальном спасброске цель получает только 5к10 психического урона, после чего эффект заканчивается.' where slug='mental-prison' and source_kind='official';

update public.spell_catalog set name_ru='Первородный оберег', effect_summary='На срок до 1 минуты с концентрацией получаешь сопротивление кислоте, холоду, огню, молнии и звуку. Когда получаешь урон одного из этих типов, реакцией можешь вместо сопротивления получить иммунитет к этому типу, включая вызвавший реакцию урон; остальные сопротивления сразу прекращаются. Иммунитет действует до конца твоего следующего хода, после чего заклинание заканчивается.', author_description='Сначала универсальная страховка от стихий, затем возможность превратить один особенно страшный удар в почти полный ноль.', author_comment='Пять сопротивлений входят в комплект. Иммунитет — аварийная кнопка, после которой комплект закрывается.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Реакция применяется к одному из пяти типов урона: кислота, холод, огонь, молния или звук.' where slug='primordial-ward' and source_kind='official';

update public.spell_catalog set name_ru='Разброс', effect_summary='Выбираешь до пяти видимых существ в пределах 30 футов. Добровольные цели телепортируются автоматически, недобровольные делают спасбросок Мудрости. Каждую затронутую цель помещаешь в видимое свободное пространство в пределах 120 футов от тебя; место назначения должно находиться на земле или полу.', author_description='Мгновенно переписывает расстановку целой группы: союзников выводит из окружения, врагов разбрасывает по неудобным позициям.', author_comment='Тактическая карта после одного действия выглядит так, будто Мастер случайно потряс стол.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Можно одновременно перемещать союзников и врагов. Спасбросок совершают только недобровольные цели.' where slug='scatter' and source_kind='official';

update public.spell_catalog set name_ru='Клетка души', effect_summary='Реакцией в момент смерти видимого гуманоида в пределах 60 футов ловишь его душу в серебряную клетку на 8 часов. Душу можно использовать до шести раз: бонусным действием восстановить 2к8 хитов, задать ей вопрос, получить преимущество на следующую атаку/проверку/спасбросок либо действием наблюдать до 10 минут за знакомым душе местом. После шестого использования душа освобождается.', author_description='Редкая утилитарная некромантия: одна пойманная душа становится запасом лечения, информации, опыта и удалённого наблюдения.', author_comment='У смерти появился интерфейс с шестью зарядами. Этические настройки в комплект не входят.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Пока душа заключена, умершего гуманоида нельзя воскресить. Разрушение клетки освобождает душу и завершает заклинание. Серебряная клетка стоимостью 100 зм не расходуется.', casting_time='1 реакция, когда видимый гуманоид в пределах 60 футов умирает', material='крошечная серебряная клетка стоимостью 100 зм — не расходуется', material_cost_gp=100, material_consumed=false, material_consumption='none' where slug='soul-cage' and source_kind='official';

update public.spell_catalog set name_ru='Призыв исчадия', effect_summary='Призываешь дух исчадия в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь форму Демона, Дьявола или Юголота; форма меняет защиту, мобильность и способы атаки. Дух действует сразу после тебя, считает тебя и назначенных тобой существ союзниками и выполняет твои команды.', author_description='Один слот — три разных боевых профиля. Выбор формы позволяет подстроить призыв под ближний бой, дальнюю атаку или особую мобильность.', author_comment='Безопасный способ работать с исчадиями: лучше призвать статблок, чем подписать контракт.', upcast='При использовании ячейки выше 6 её уровень используется в характеристиках духа, увеличивая хиты, атаки и другие параметры статблока.', notes='Требуется концентрация. Фокус — кровь гуманоида в рубиновом сосуде стоимостью не менее 600 зм; не расходуется.', material='кровь гуманоида в рубиновом сосуде стоимостью не менее 600 зм — не расходуется', material_cost_gp=600, material_consumed=false, material_consumption='none' where slug='summon-fiend' and source_kind='official';

update public.spell_catalog set name_ru='Потусторонний облик Таши', effect_summary='Бонусным действием принимаешь потусторонний облик на срок до 1 минуты с концентрацией, выбирая Нижние или Верхние планы. Получаешь две тематические иммунности к урону/состоянию, скорость полёта 40 футов, +2 к КД, магические атаки оружием с возможностью использовать заклинательную характеристику вместо Силы или Ловкости и возможность атаковать дважды действием Атака.', author_description='Это почти временный боевой подкласс: защита, полёт, усиленное оружие и дополнительная атака появляются одной бонусной кнопкой.', author_comment='Таша посмотрела на превращения и решила, что выбирать между магом и бойцом вообще необязательно.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Нижние планы дают иммунитет к огню и яду, а также к Отравлению; Верхние — иммунитет к излучению и некротическому урону, а также к Очарованию. Фокус стоимостью 500+ зм не расходуется.', material='предмет с выгравированным символом Внешних планов стоимостью не менее 500 зм — не расходуется', material_cost_gp=500, material_consumed=false, material_consumption='none' where slug='tasha-s-otherworldly-guise' and source_kind='official';

update public.spell_catalog set name_ru='Преображение Тензера', effect_summary='На срок до 10 минут с концентрацией превращаешь себя в боевого мага: получаешь 50 временных хитов, преимущество на атаки простым и воинским оружием, владение таким оружием, доспехами и щитами, владение спасбросками Силы и Телосложения, можешь атаковать дважды действием Атака и наносишь каждым попаданием оружием дополнительно 2к12 урона силовым полем. Пока эффект действует, ты не можешь творить заклинания.', author_description='Очень дорогой по уровню слот за право временно перестать быть хрупким заклинателем и начать решать проблемы оружием.', author_comment='Тензер изобрёл способ потратить шестую ячейку на фразу «ладно, теперь я сам пойду в ближний бой».', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='После окончания сделай спасбросок Телосложения Сл 15; при провале получаешь 1 уровень Истощения. Материальный компонент — несколько волосков быка, не расходуются.', material='несколько волосков быка — не расходуются', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='tenser-s-transformation' and source_kind='official';

commit;
